window.TP3B["camara:221338"] = [{"t":"PL","n":"3461","y":"2026","e":"Altera a Lei nº 9.394, de 20 de dezembro de 1996 (Lei de Diretrizes e Bases da Educação Nacional), para estabelecer a responsabilidade objetiva do Poder Público por riscos no ambiente escolar e para equiparar a violência contra profissionais da educação a acidente de trabalho.","d":"2026-07-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-09-08","ds":"Recebimento pelo(a) CE.","id":"2637110","law":false,"r":"m"},{"t":"PL","n":"3225","y":"2026","e":"Altera a Lei nº 11.738, de 16 de julho de 2008, para estabelecer diretrizes nacionais para o cumprimento, na modalidade de Planejamento Domiciliar Docente, de parte da jornada reservada às atividades extraclasse dos profissionais do magistério público da educação básica.","d":"2026-06-18","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-08-21","ds":"Recebimento pelo(a) CE.","id":"2634381","law":false,"r":"c"},{"t":"PEC","n":"13","y":"2026","e":"Altera o art. 9º da Emenda Constitucional nº 132, de 20 de dezembro de 2023, para permitir a concessão de créditos do Imposto sobre Bens e Serviços através de fomento indireto a doadores e patrocinadores de projetos culturais e esportivos.","d":"2026-06-10","o":"in_progress","s":"Pronta para Pauta","tr":"Notificações","u":"2026-07-20","ds":"Indeferido o Requerimento n. 3492/2026.","id":"2631190","law":false,"r":"c"},{"t":"PL","n":"1754","y":"2026","e":"Institui a TerraBras, empresa pública destinada à defesa da soberania nacional e ao aproveitamento dos minerais críticos ou estratégicos; estabelece o regime de partilha da produção mineral; altera o Decreto-Lei nº 227, de 28 de fevereiro de 1967, a Lei nº 8.970, de 28 de dezembro de 1994, e a Lei nº 13.575, de 26 de dezembro de 2017; e dá outras providências.","d":"2026-04-10","o":"status_not_published","s":"","tr":"Apresentação de Requerimento","u":"2026-04-22","ds":"Apresentação do REQ n. 2187/2026 (Requerimento de Apensação), pelo Deputado Pedro Uczai (PT/SC -Fdr PT-PCdoB-PV), que \"Requer a apensação, para tramitação conjunta, do Projeto de Lei nº 1754, de 2026, ao Projeto de Lei nº 2780, de 2024\".","id":"2615287","law":false,"r":"c"},{"t":"PL","n":"1307","y":"2026","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), e o Decreto-Lei nº 1.001, de 21 de outubro de 1969 (Código Penal Militar), para estabelecer a competência da Justiça Comum para o processamento e julgamento do crime de feminicídio cometido por militares (Lei Gisele Alves Santana).","d":"2026-03-20","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apensação","u":"2026-05-15","ds":"Apensação desta proposição ao PL 1189/2026.","id":"2611028","law":false,"r":"c"},{"t":"PL","n":"1107","y":"2026","e":"Institui pensão especial para pessoas com deficiência decorrente de violência doméstica e familiar; altera a Lei nº 8.213, de 24 de julho de 1991, para dispensar do cumprimento de carência o requerente de auxílio por incapacidade temporária e aposentadoria por incapacidade permanente decorrente de violência doméstica e familiar; e altera a Lei nº 11.340, de 7 de agosto de 2006, a fim de dispor sobre determinação judicial de avaliação médica, para fins de instrução do pedido de pensão especial, em caso de violência doméstica e familiar que resulte em aquisição de deficiência permanente pela ofendida ou pelo ofendido.","d":"2026-03-11","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-09-01","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 04/08/2026 a 01/09/2026). Não foram apresentadas emendas ao substitutivo.","id":"2608238","law":false,"r":"c"},{"t":"PL","n":"985","y":"2026","e":"Institui o Programa Nacional de Renda e Reingresso Produtivo para Mulheres em Situação de Violência Doméstica e Familiar e dá outras providências.","d":"2026-03-05","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-07-20","ds":"Designada Relatora, Dep. Camila Jara (PT-MS), para o PL 6731/2025, ao qual esta proposição está apensada.","id":"2607378","law":false,"r":"c"},{"t":"PLP","n":"41","y":"2026","e":"Dispõe sobre o Sistema Nacional de Enfrentamento da Violência contra Meninas e Mulheres e a destinação de recursos às ações de enfrentamento ao feminicídio e de garantia da vida de meninas e mulheres.","d":"2026-03-03","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2026-07-15","ds":"Remessa ao Senado Federal por meio do Of. nº 171/2026/SGM-P.","id":"2606313","law":false,"r":"c"},{"t":"PL","n":"805","y":"2026","e":"Dispõe sobre o enfrentamento à violência digital contra as mulheres por sua condição de mulher, com base na Lei Modelo Interamericana para Prevenir, Punir e Erradicar a Violência Digital de Gênero contra as Mulheres, elaborada no âmbito da Organização dos Estados Americanos (OEA).","d":"2026-02-26","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-05-05","ds":"Designado Relator, Dep. Orlando Silva (PCdoB-SP).","id":"2605145","law":false,"r":"c"},{"t":"PL","n":"777","y":"2026","e":"Altera a Lei nº 11.738, de 16 de julho de 2008, para estabelecer que o piso salarial profissional nacional do magistério público da educação básica corresponde ao vencimento inicial da carreira, vedada a sua composição por meio de abonos, prêmios, subsídios ou outras vantagens pecuniárias, e tipifica o seu descumprimento como ato de improbidade administrativa.","d":"2026-02-25","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-08-03","ds":"Parecer do Relator, Dep. Reimont (PT-RJ), pela aprovação.","id":"2604850","law":false,"r":"m"},{"t":"PL","n":"6222","y":"2025","e":"Institui a Mobilização Nacional dos 21 Dias de Ativismo pelo Fim da Violência contra as Mulheres, realizado anualmente, entre 20 de novembro e 10 de dezembro, destinado a intensificar ações de prevenção, enfrentamento e superação das violências contra as mulheres, por meio de articulação nacional entre o poder público, os entes federativos, a sociedade civil e a iniciativa privada.","d":"2025-12-08","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2026-03-18","ds":"Remessa ao Senado Federal por meio do Of. nº 50/2026/SGM-P.","id":"2593723","law":false,"r":"c"},{"t":"PL","n":"6149","y":"2025","e":"Acrescenta a misoginia como motivo de discriminação nos crimes definidos na Lei nº 7.716, de 5 de janeiro de 1989.","d":"2025-12-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2026-02-02","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 03/02/2026.","id":"2592113","law":false,"r":"m"},{"t":"PL","n":"5736","y":"2025","e":"Dispõe sobre o atendimento de crianças e adolescentes vítimas de violência sexual e a garantia dos seus direitos","d":"2025-11-06","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2026-03-16","ds":"Apensação do PL 6364/2025 a esta proposição.","id":"2582519","law":false,"r":"c"},{"t":"PL","n":"5462","y":"2025","e":"Institui a Plataforma Escola Cuidada e dispõe sobre a transparência e o planejamento da adaptação das escolas da educação básica às mudanças climáticas.","d":"2025-10-28","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2026-02-02","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 03/02/2026.","id":"2578344","law":false,"r":"c"},{"t":"PL","n":"5362","y":"2025","e":"Dispõe sobre a isenção do pagamento da tarifa nos serviços de transporte coletivo às pessoas regularmente inscritas em concursos públicos e/ou em dias de provas de caráter oficial, educacional ou funcional público, em todo território nacional, exclusivamente nos dias de realização das provas.","d":"2025-10-22","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-04-22","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 09/04/2026 a 22/04/2026). Não foram apresentadas emendas.","id":"2574917","law":false,"r":"m"},{"t":"PL","n":"5286","y":"2025","e":"Institui a Política Nacional de Combate ao Racismo Ambiental e dá outras providências.","d":"2025-10-21","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-05-29","ds":"Apensação do PL 1502/2026 a esta proposição.","id":"2573501","law":false,"r":"c"},{"t":"PL","n":"5003","y":"2025","e":"Dispõe sobre a regulação do consumo de recursos hídricos por centros de processamento de dados (data centers) no território nacional, com vistas à preservação da soberania hídrica da população, e dá outras providências.","d":"2025-10-07","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apensação","u":"2025-11-10","ds":"Apensação desta proposição ao PL 2080/2025.","id":"2567990","law":false,"r":"c"},{"t":"PL","n":"4819","y":"2025","e":"Acrescenta dispositivo ao art. 3º da Lei nº 9.250, de 26 de dezembro de 1995, para fixar a incidência do Imposto sobre a Renda das Pessoas Físicas somente em relação ao rendimento de maior valor recebido pelo exercício da docência.","d":"2025-09-29","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-11-10","ds":"Recebimento pela CE.","id":"2565410","law":false,"r":"m"},{"t":"PL","n":"4687","y":"2025","e":"Acrescenta e altera dispositivos da Lei nº 7.713, de 22 de dezembro de 1988, para isentar do Imposto sobre a Renda das Pessoas Físicas os rendimentos de professores e demais profissionais da educação básica e superior.","d":"2025-09-19","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-11-10","ds":"Recebimento pela CE.","id":"2562627","law":false,"r":"m"},{"t":"PL","n":"4617","y":"2025","e":"Reduz a zero as alíquotas do Imposto sobre Produtos Industrializados – IPI, da Contribuição para o PIS/PASEP e do Imposto de Importação incidentes sobre veículos novos, adquiridos por servidores públicos, ativos e inativos, integrantes das carreiras da segurança pública de todos os entes, a serem blindados com a finalidade de proteção dos agentes públicos e dá outras providências.","d":"2025-09-16","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2025-11-10","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 11/11/2025.","id":"2561365","law":false,"r":"m"},{"t":"PL","n":"4317","y":"2025","e":"Acrescenta e altera dispositivos da Lei nº 7.713, de 22 de dezembro de 1988, para isentar do Imposto sobre a Renda das Pessoas Físicas os rendimentos dos professores da educação básica e superior, inclusive proventos, resultantes de seu trabalho docente, no âmbito do território nacional.","d":"2025-08-28","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2025-09-24","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 25/09/2025 PÁG 529.","id":"2554694","law":false,"r":"m"},{"t":"PL","n":"3891","y":"2025","e":"Altera a Lei nº 12.965, de 23 de abril de 2014 (Marco Civil da Internet), para dispor sobre a responsabilização pessoal dos representantes legais, em território nacional, por provedores de aplicações de internet em relação a conteúdos que promovem a 'adultização' infantil e a pedofilia.","d":"2025-08-11","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Apresentação de Proposição","u":"2025-08-11","ds":"Apresentação do PL n. 3891/2025 (Projeto de Lei), pela Deputada Professora Luciene Cavalcante (PSOL/SP -Fdr PSOL-REDE), que \"Altera a Lei nº 12.965, de 23 de abril de 2014 (Marco Civil da Internet), para dispor sobre a responsabilização pessoal dos representantes legais, em território nacional, por provedores de aplicações de internet em relação a conteúdos que promovem a 'adultização' infantil e ","id":"2542395","law":false,"r":"m"},{"t":"PL","n":"3871","y":"2025","e":"Veda a divulgação ou a exibição de propagandas de casas ou aplicativos de apostas (bets) em equipamentos públicos, mesmo em casos de concessão ou permissão de uso.","d":"2025-08-11","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-05-25","ds":"Designada Relatora, Dep. Delegada Ione (PL-MG).","id":"2542221","law":false,"r":"m"},{"t":"PL","n":"3674","y":"2025","e":"Altera o art. 2º, §§ 1º e 2º, da Lei 11.738, de 16 de julho de 2008, que instituiu o piso salarial profissional nacional para os profissionais do magistério público da educação básica, para reduzir a jornada máxima para trinta horas semanais.","d":"2025-08-01","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-08-06","ds":"Parecer da Relatora, Dep. Socorro Neri (PP-AC), pela aprovação do PL 3674/25 e pela rejeição do PL 2821/26, apensado.","id":"2539230","law":false,"r":"m"},{"t":"PL","n":"3673","y":"2025","e":"Altera a Lei nº 9.394, de 20 de dezembro de 1996 (Lei de Diretrizes e Bases da Educação Nacional), para dispor sobre a contratação de profissionais do magistério por tempo determinado para atender à necessidade temporária de excepcional interesse público no âmbito dos sistemas de ensino dos Estados, do Distrito Federal e dos Municípios; e dá outras providências","d":"2025-08-01","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-06-16","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 29/05/2026 a 16/06/2026). Foi apresentada uma emenda.","id":"2539229","law":false,"r":"m"},{"t":"PL","n":"2479","y":"2025","e":"Dispõe sobre o valor mínimo de remuneração para serviços de trabalhadores de plataformas digitais de entregas e mototaxistas, estabelece regras de transparência, cria obrigação de seguro de acidentes e dá outras providências.","d":"2025-05-22","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-03-18","ds":"Designado Relator, Dep. Max Lemos (PDT-RJ).","id":"2515591","law":false,"r":"c"},{"t":"PL","n":"2223","y":"2025","e":"Insere o §4º no Art. 141 e o §14 no art. 129 no Decreto-Lei  nº 2.848, de 7 de dezembro de 1940 (Código Penal), agravando e qualificando os crimes contra a honra e lesão corporal contra profissionais da educação.","d":"2025-05-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-06-12","ds":"Recebimento pela CCJC.","id":"2507171","law":false,"r":"m"},{"t":"PLP","n":"99","y":"2025","e":"Insere o §4º no Art. 141 e o §14 no art. 129 no Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), agravando e qualificando os crimes contra a honra e lesão corporal contra profissionais da educação.","d":"2025-04-22","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2025-06-16","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 17/06/2025.","id":"2498420","law":false,"r":"m"},{"t":"PDL","n":"154","y":"2025","e":"Susta a Resolução CFM N° 2.427, de 8 de abril de 2025, publicada em 16 de abril de 2025, que revisa os critérios éticos e técnicos para o atendimento às pessoas com incongruência e/ou disforia de gênero, e dá outras providências.","d":"2025-04-17","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-05-14","ds":"Designada Relatora, Dep. Duda Salabert (PSOL-MG).","id":"2498358","law":false,"r":"c"},{"t":"PL","n":"791","y":"2025","e":"Dispõe sobre a criação do Programa Nacional de Incentivo à Educação Continuada para Mães Solo e dá outras providências.","d":"2025-03-07","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-05-18","ds":"Designada Relatora, Dep. Talíria Petrone (PSOL-RJ).","id":"2486073","law":false,"r":"c"},{"t":"PEC","n":"8","y":"2025","e":"Dá nova redação ao inciso XIII, do artigo 7° da Constituição Federal para dispor sobre a redução da jornada de trabalho para quatro dias por semana no Brasil.","d":"2025-02-25","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2026-05-27","ds":"Desapensação desta da PEC nº 221, de 2019, principal, em face da aprovação, em Plenário, da Proposta de Emenda à Constituição n° 221, de 2019. (Sessão Deliberativa Extraordinária Presencial de 27/05/2026 - 15:00 - 106ª Sessão)","id":"2485341","law":false,"r":"c"},{"t":"PL","n":"625","y":"2025","e":"Institui o “Selo Compromisso com a Primeiríssima Infância”.","d":"2025-02-21","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Recebimento - Redação Final","u":"2025-10-20","ds":"Apresentação da RDF n. 1 PLEN (Redação Final), pela Deputada Denise Pessôa (PT/RS -Fdr PT-PCdoB-PV).","id":"2485142","law":false,"r":"m"},{"t":"PL","n":"502","y":"2025","e":"Altera a Lei nº 14.016, de 2020, para vedar o descarte de alimentos, criminalizar a prática, especialmente no contexto das empresas que se desfazem de alimentos em razão da redução de preços, e incentiva o estímulo a doação de alimentos para iniciativas de segurança alimentar e combate à fome.","d":"2025-02-18","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-08-10","ds":"Designado Relator, Dep. Kiko Celeguim (PT-SP).","id":"2484246","law":false,"r":"c"},{"t":"PLP","n":"15","y":"2025","e":"Altera a Lei Complementar nº 200, de 30 de agosto de 2023 (Arcabouço fiscal) que “Institui regime fiscal sustentável para garantir a estabilidade macroeconômica do País e criar as condições adequadas ao crescimento socioeconômico”, a fim de retirar os recursos destinados ao Programa Nacional de Alimentação Escolar (PNAE) do teto de gastos.","d":"2025-02-06","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-05-06","ds":"Designado Relator, Dep. Paulo Lemos (PT-AP).","id":"2483155","law":false,"r":"m"},{"t":"PL","n":"194","y":"2025","e":"Institui o Auxílio Emergencial para Repatriados Forçados, destinado a cidadãos brasileiros deportados ou expulsos de país estrangeiro, com o objetivo de garantir condições mínimas para sua reinserção social e econômica no Brasil.","d":"2025-02-04","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-07-06","ds":"Encaminhada à publicação. Parecer da Comissão de Relações Exteriores e de Defesa Nacional Publicado em avulso e no DCD de 07/07/2026, Letra A.","id":"2482655","law":false,"r":"c"},{"t":"PL","n":"69","y":"2025","e":"Altera o Decreto-Lei 2.848 de 7 de dezembro de 1940- Código Penal, a Lei 11.340 de 7 de agosto de 2006 - Lei Maria da Penha, e a Lei 10.741 de 1º de outubro de 2003 – Estatuto do Idoso, para tipificar o estelionato sentimental como crime de alto potencial ofensivo, tornando-o um crime separado e aumentando a pena, destacando a gravidade do crime.","d":"2025-02-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-12-05","ds":"Recebimento pela CCJC.","id":"2482276","law":false,"r":"c"},{"t":"PL","n":"127","y":"2025","e":"Dispõe sobre a suspensão da remuneração e proventos de militares investigados por violações de direitos humanos e crimes contra a humanidade, praticados durante o período da Ditadura Militar, até a prolação de decisão definitiva no processo judicial.","d":"2025-02-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-04-30","ds":"Recebimento pela CREDN.","id":"2482465","law":false,"r":"c"},{"t":"PL","n":"3620","y":"2024","e":"Estabelece critérios para a suspensão do Benefício de Prestação Continuada (BPC) de que trata o Art.21-B da Lei nº 8.742, de 7 de dezembro de 1993.","d":"2024-09-18","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2025-10-08","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 29/09/2025 a 08/10/2025). Não foram apresentadas emendas ao substitutivo.","id":"2458622","law":false,"r":"c"},{"t":"PL","n":"3385","y":"2024","e":"Declara a Dublagem Brasileira como Patrimônio Cultural Imaterial Nacional.","d":"2024-08-29","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-10-02","ds":"Recebimento pela CCJC.","id":"2456063","law":false,"r":"m"},{"t":"PEC","n":"31","y":"2024","e":"Acrescenta os arts.91-A, 91-B e a alínea “g” do inciso I do artigo 159 da Constituição Federal, para instituir o Conselho Nacional de Mudança Climática, a Autoridade Climática Nacional e o Fundo Nacional de Mudança Climática.","d":"2024-08-27","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2024-08-27","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2455515","law":false,"r":"c"},{"t":"PLP","n":"136","y":"2024","e":"Altera a Lei Complementar nº79, de 7 de janeiro de 1994, e a Leinº 13.756, de 12 de dezembro de 2018, para dispor, expressamente, sobre a aplicação de recursos do Fundo Penitenciário Nacional (FUPEN) e do Fundo Nacional de Segurança Pública (FNSP) em órgãos e entidadesque implementam ações de prevenção e enfrentamento da violência contra a mulher nos âmbitos estadual e municipal.","d":"2024-08-21","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2024-12-13","ds":"Remessa ao Senado Federal por meio do Of. nº 199/2024/SGM-P.","id":"2454257","law":false,"r":"c"},{"t":"PL","n":"2947","y":"2024","e":"Altera o art. 47 da Lei nº 12.351, de 22 de dezembro de 2010, para incluir a Política Nacional de Cuidados entre os programas e projetos beneficiados pelo Fundo Social.","d":"2024-07-17","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-10-14","ds":"Encaminhada à publicação. Parecer da Comissão de Previdência, Assistência Social, Infância, Adolescência e Família Publicado em avulso e no DCD de 15/10/2025, Letra B.","id":"2449804","law":false,"r":"c"},{"t":"PEC","n":"27","y":"2024","e":"Altera a Constituição Federal para acrescentar o Capítulo IX - Da Promoção Da Igualdade Racial, que institui o Fundo Nacional de Reparação Econômica e de Promoção da Igualdade Racial (FNREPIR) com o objetivo de promover a igualdade de oportunidades e a inclusão social dos brasileiros pretos e pardos, e dá outras providências","d":"2024-07-08","o":"status_not_published","s":"","tr":"Encerramentos","u":"2026-03-18","ds":"Matéria não apreciada em face do encerramento da Ordem do Dia.","id":"2447265","law":false,"r":"c"},{"t":"PL","n":"2100","y":"2024","e":"Dispõe sobre a remissão total de dívidas de agricultores familiares e cooperativas de agricultores familiares em municípios do Estado do Rio Grande do Sul impactados por calamidade pública.","d":"2024-05-28","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2024-05-28","ds":"Apresentação do PL n. 2100/2024 (Projeto de Lei), pelo Deputado Ivan Valente (PSOL/SP -Fdr PSOL-REDE) e outros, que \"Dispõe sobre a remissão total de dívidas de agricultores familiares e cooperativas de agricultores familiares em municípios do Estado do Rio Grande do Sul impactados por calamidade pública. \n\".","id":"2436844","law":false,"r":"c"},{"t":"PEC","n":"23","y":"2024","e":"Acrescenta o §2º no Art. 4º da Constituição para acrescentar a integração dos países de língua portuguesa entre os princípios que regem as relações internacionais da República Federativa do Brasil.","d":"2024-05-27","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2024-05-27","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2436619","law":false,"r":"c"},{"t":"PEC","n":"20","y":"2024","e":"Institui o Regime Extraordinário Fiscal, Financeiro e de Contratações destinado ao enfrentamento de calamidade pública e à reconstrução da infraestrutura física e social no Estado do Rio Grande do Sul, bem como ao suporte direto às famílias afetadas.","d":"2024-05-21","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2025-04-15","ds":"Designado Relator, Dep. Alencar Santana (PT-SP).","id":"2435133","law":false,"r":"c"},{"t":"PL","n":"1908","y":"2024","e":"Altera a Lei nº 9.656, de 3 de junho de 1998 (Lei dos Planos de Saúde), para incluir novos requisitos quando do cancelamento unilateral dos planos coletivos empresariais ou por adesão de pessoas idosas, pessoas com deficiência, pessoas com transtorno do espectro autista, pessoas com enfermidades graves, doenças raras e paralisia cerebral, e pessoas em tratamentos contínuos e especiais; e dá outras providências.","d":"2024-05-17","o":"status_not_published","s":"","tr":"Notificacao para Publicação Intermediária","u":"2025-08-15","ds":"Designado Relator, Dep. Pedro Westphalen (PP-RS), para o PL 1408/2023, ao qual esta proposição está apensada.","id":"2434528","law":false,"r":"m"},{"t":"PL","n":"1896","y":"2024","e":"Institui auxílio emergencial aos micro e pequenos empreendedores da área da cultura do Rio Grande do Sul.","d":"2024-05-16","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Apresentação de Requerimento","u":"2024-05-28","ds":"Apresentação do REQ n. 1819/2024 (Requerimento de Urgência (Art. 155 do RICD)), pela Deputada Fernanda Melchionna (PSOL/RS -Fdr PSOL-REDE) e outros, que \"Requer, na forma regimental, a tramitação em regime de urgência do PL nº 1896/2024, que “Institui auxílio emergencial aos micro e pequenos empreendedores da área da cultura do Rio Grande do Sul”\".","id":"2434444","law":false,"r":"c"},{"t":"PL","n":"1831","y":"2024","e":"Altera a Lei nº 6.404, de 15 de dezembro de 1976, para dispor sobre a participação de empregados nos conselhos de administração das empresas de capital aberto ou fechado que tenham 300 empregados ou mais.","d":"2024-05-15","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2024-05-20","ds":"Recebimento pela CTRAB.","id":"2433893","law":false,"r":"c"},{"t":"PL","n":"1820","y":"2024","e":"Inclui, entre as disposições que devem estar contidas nos planos diretores municipais, a previsão de cobertura de, no mínimo, 50% (cinquenta por cento) da área dos estacionamentos que possuam número de vagas igual ou superior a oitenta veículos com painéis para geração de energia solar e, com esse objetivo, altera a Lei nº 10.257, de 10 de julho de 2001.","d":"2024-05-14","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-04-29","ds":"Designado Relator, Dep. Junio Amaral (PL-MG), para o PL 5384/2023, ao qual esta proposição está apensada.","id":"2433590","law":false,"r":"c"},{"t":"PLP","n":"80","y":"2024","e":"Institui o Regime de Recuperação Socioambiental (RRS) para o Estado do Rio Grande do Sul, revoga o Regime de Recuperação Fiscal (RRF) e dá outras providências.","d":"2024-05-08","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Notificação de Despacho","u":"2024-05-09","ds":"Deferido o REQ 1516/2024.","id":"2432000","law":false,"r":"c"},{"t":"PL","n":"1647","y":"2024","e":"Dispõe sobre a isenção de Imposto de Renda para vítimas da calamidade no Rio Grande do Sul no exercício financeiro corrente e dá outras providências.","d":"2024-05-08","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Análise)","tr":"Apresentação de Proposição","u":"2024-05-08","ds":"Apresentação do PL n. 1647/2024 (Projeto de Lei), pela Deputada Fernanda Melchionna (PSOL/RS -Fdr PSOL-REDE) e outros, que \"Dispõe sobre a isenção de Imposto de Renda para vítimas da calamidade no Rio Grande do Sul no exercício financeiro corrente e dá outras providências\n\".","id":"2431999","law":false,"r":"c"},{"t":"PL","n":"1594","y":"2024","e":"Institui a Política Nacional dos Deslocados Ambientais e Climáticos – PNDAC, estabelecendo seus direitos e fornecendo diretrizes para que o Poder Público promova sua proteção.","d":"2024-05-07","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Publicação de Proposição","u":"2024-07-10","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD 11/07/2024 PAG 5043","id":"2431186","law":false,"r":"c"},{"t":"PL","n":"1559","y":"2024","e":"Altera a Lei nº 9.394, de 20 de dezembro de 1996 (Lei de Diretrizes e Bases da Educação Nacional), para vedar o uso de inteligência artificial como parâmetro de referência e de métrica para o desenvolvimento de material pedagógico, bem como ferramenta de avaliação de desempenho escolar, a ser utilizado pela rede pública de ensino das unidades da Federação, e dá outras providências correlatas.","d":"2024-05-06","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-05-04","ds":"Designado Relator, Dep. Pedro Uczai (PT-SC).","id":"2430998","law":false,"r":"m"},{"t":"PLP","n":"57","y":"2024","e":"Cria a Fundação de Amparo à Enfermagem Brasileira e dá outras providências.","d":"2024-04-16","o":"in_progress","s":"Pronta para Pauta","tr":"Apresentação de Requerimento","u":"2025-10-28","ds":"Apresentação do REQ n. 4517/2025 (Requerimento de Urgência (Art. 155 do RICD)), pelos Deputado Rodrigo Gambale (PODE/SP) e outros, que \"Requer urgência para o PLP 57/2024, que Cria a Fundação de Amparo à Enfermagem Brasileira e dá outras providências\".","id":"2427181","law":false,"r":"m"},{"t":"PL","n":"1030","y":"2024","e":"Altera os artigos 21 e 30 da Lei nº 8.935, de 18 de novembro de 1994 para resguardar direitos trabalhistas dos prepostos de serviços notariais e de registro.","d":"2024-03-28","o":"in_progress","s":"Aguardando Parecer","tr":"Apresentação de Requerimento","u":"2026-03-18","ds":"Apresentação do REQ n. 1496/2026 (Requerimento de Desapensação), pelo Deputado Rodrigo Gambale (PODE/SP), que \"Requer a desapensação do PL 357/2026 da árvore de apensados ao PL 1030/2024\".","id":"2424100","law":false,"r":"m"},{"t":"PL","n":"1022","y":"2024","e":"Dispõe sobre a criação do “Programa de Enfrentamento à Crise e Emergência Climática nas Escolas” nas unidades de ensino da rede pública, nos níveis básico, técnico e superior.","d":"2024-03-27","o":"status_not_published","s":"","tr":"Notificações","u":"2025-06-12","ds":"Designada Relatora, Dep. Sâmia Bomfim (PSOL-SP), para o PL 1185/2019, ao qual esta proposição está apensada.","id":"2424042","law":false,"r":"m"},{"t":"PL","n":"861","y":"2024","e":"Estabelece adicional de insalubridade aos policiais penais em decorrência da exposição à radiação ionizante e agentes biológicos contagiosos.","d":"2024-03-19","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-04-17","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 18/04/2024 PAG 308","id":"2421937","law":false,"r":"m"},{"t":"PLP","n":"23","y":"2024","e":"Altera a Lei Complementar nº 87, de 13 de setembro de 1996 (Lei Kandir) que “Dispõe sobre o imposto dos Estados e do Distrito Federal sobre operações relativas à circulação de mercadorias e sobre prestações de serviços de transporte interestadual e intermunicipal e de comunicação, e dá outras providências”, a fim de vetar isenção tributária para exportação de animais vivos.","d":"2024-03-14","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-09-19","ds":"Encaminhada à publicação. Parecer da Comissão de Meio Ambiente e Desenvolvimento Sustentável Publicado no DCD de 20/09/2025, Letra B.","id":"2421309","law":false,"r":"m"},{"t":"PL","n":"784","y":"2024","e":"Dispõe sobre a rotulagem obrigatória dos produtos de origem animal produzidos e comercializados em território nacional com o intuito de dar clareza aos consumidores.","d":"2024-03-14","o":"in_progress","s":"Pronta para Pauta","tr":"Aprovação de Requerimento","u":"2025-09-17","ds":"Aprovado o requerimento nº 178/2025,do Sr. Pezenti que Solicita redistribuição do Projeto de Lei nº 784/2024 que “Dispõe sobre a rotulagem obrigatória dos produtos de origem animal produzidos e comercializados em território nacional com o intuito de dar clareza aos consumidores.” para análise de mérito na Comissão de Agricultura, Pecuária, Abastecimento e Desenvolvimento Rural (CAPADR).","id":"2421307","law":false,"r":"m"},{"t":"PL","n":"783","y":"2024","e":"Dispõe sobre a proibição de descarte de pintinhos machos recém eclodidos por meio da adoção de tecnologias de sexagem in ovo.","d":"2024-03-14","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificação de Apensação","u":"2026-09-03","ds":"Apensação do PL 3034/2026 a esta proposição.","id":"2421303","law":false,"r":"m"},{"t":"PL","n":"782","y":"2024","e":"Altera os arts. 141 e 145 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) para aumentar a pena e tornar a ação pública incondicionada nos casos de crimes contra a honra que desrespeitam violações de Direitos Humanos e violência política de gênero sofridas pela vítima.","d":"2024-03-14","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2024-09-11","ds":"Designada Relatora, Dep. Chris Tonietto (PL-RJ)","id":"2421301","law":false,"r":"m"},{"t":"PL","n":"583","y":"2024","e":"Assegura que os entregadores de aplicativo não são obrigados a subir até a porta das unidades habitacionais ou comerciais dos consumidores e dá outras providências","d":"2024-03-06","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-06-30","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 03/06/2026 a 30/06/2026). Não foram apresentadas emendas ao substitutivo.","id":"2419445","law":false,"r":"c"},{"t":"PEC","n":"6","y":"2024","e":"Altera o inciso X do § 22 e insere o § 21-A no art. 40 da Constituição, altera o art. 11 da Emenda Constitucional nº 103, de 12 de novembro de 2019 e revoga os §§ 1º-A, 1º-B e 1º-C do art. 149 da Constituição e o § 8º do art. 9º da Emenda Constitucional nº 103, de 2019.","d":"2024-03-05","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2026-08-12","ds":"Apresentação do REQ n. 4034/2026 (Requerimento de Apensação), pelo Deputado Márcio Biolchi (MDB/RS), que \"Requeiro a Vossa Excelência, nos termos dos arts. 142 e 143, inciso II, do Regimento Interno da Câmara dos Deputados, o apensamento da PEC nº 6, de 2024, que “Altera o inciso X do § 22 e insere o § 21-A no art. 40 da Constituição, altera o art. 11 da Emenda Constitucional nº 103, de 12 de nove","id":"2419252","law":false,"r":"c"},{"t":"PL","n":"475","y":"2024","e":"Institui direitos para o combate à discriminação de gestantes e parturientes e de pessoas que exercem cuidado de uma ou mais crianças e que sejam candidatas em processos seletivos de bolsas de graduação e pós-graduação.\n\nNOVA EMENTA: Veda a adoção de critérios discriminatórios contra estudantes e pesquisadores em virtude de gestação, de parto, de nascimento de filho ou de adoção ou obtenção de guarda judicial para fins de adoção nos processos de seleção para bolsas de estudo e pesquisa das instituições de educação superior e das agências de fomento à pesquisa.","d":"2024-02-28","o":"approved","s":"Transformado em Norma Jurídica","tr":"Apresentação de Proposição","u":"2025-04-28","ds":"Apresentação do DOC n. 329/2025 (Ofício do Senado Federal), pelo Senado Federal, que \"Ofício SF nº 314/2025 que comunica restituição de Projeto de Lei sancionado\".","id":"2418789","law":true,"r":"c"},{"t":"PL","n":"5983","y":"2023","e":"Altera a Lei 9.394, de 20 de dezembro de 1996, para dispor sobre o ensino de arte no âmbito da educação básica.","d":"2023-12-12","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2025-04-09","ds":"Designada Relatora, Dep. Adriana Ventura (NOVO-SP)","id":"2412556","law":false,"r":"c"},{"t":"PL","n":"5982","y":"2023","e":"Altera a Lei nº 9.504, de 30 de setembro de 1997, para limitar o reajuste anual do Fundo Especial de Financiamento de Campanha.","d":"2023-12-12","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-12-15","ds":"Parecer do Relator, Dep. Kim Kataguiri (UNIÃO-SP), pela compatibilidade e adequação financeira e orçamentária; e, no mérito, pela aprovação.","id":"2412555","law":false,"r":"c"},{"t":"PL","n":"5889","y":"2023","e":"Dispõe sobre a restrição do uso de tecnologias de reconhecimento facial pelo Poder Público.","d":"2023-12-06","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2023-12-14","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 15/12/2023.","id":"2410210","law":false,"r":"m"},{"t":"PL","n":"5888","y":"2023","e":"Altera o art. 5º, parágrafo único, da Lei 11.738/2008, para incluir os parágrafos 1º e 2º em mesmo artigo, citando a remissão à Lei 14.113, de 25 de dezembro de 2.020 (Nova Lei do Fundeb) quanto à atualização do Piso Nacional do Magistério e para constar como obrigatório o pagamento deste piso para pagamento do abono previsto no artigo 26, §2º da Lei 14.113, de 25 de dezembro de 2.020.","d":"2023-12-06","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-06-11","ds":"Designado Relator, Dep. João Maia (PP-RN), para o PL 698/2011, ao qual esta proposição está apensada.","id":"2410209","law":false,"r":"m"},{"t":"PL","n":"5618","y":"2023","e":"Institui o Termo Territorial Coletivo como instrumento urbanístico de gestão territorial caracterizado pela gestão coletiva da propriedade da terra, pela titularidade individual das construções e pela autonomia de ingresso, visando à sustentabilidade da habitação de interesse social e da outras providências.","d":"2023-11-21","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-07-14","ds":"Encaminhada à publicação. Parecer da Comissão de Desenvolvimento Urbano Publicado em avulso e no DCD de 15/07/2025, Letra A.","id":"2405321","law":false,"r":"c"},{"t":"PL","n":"5607","y":"2023","e":"Altera o §4º do art. 1º da Lei nº 11.079, de 30 de dezembro de 2004, para acrescentar o inciso IV, proibindo a contratação de parceria público-privada para prestação de serviços, obras públicas, fornecimento e instalação de bens de garantia ao direito fundamental à educação.","d":"2023-11-21","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-12-03","ds":"Parecer da Relatora, Dep. Adriana Ventura (NOVO-SP), pela aprovação, com substitutivo.","id":"2405112","law":false,"r":"m"},{"t":"PL","n":"5092","y":"2023","e":"Proíbe a utilização de gaiolas e sistemas de confinamento extremo de animais criados para a alimentação humana e extração de penas e peles e dá outras providências.","d":"2023-10-20","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2025-09-30","ds":"Devolvida pelo Relator sem Manifestação.","id":"2397979","law":false,"r":"m"},{"t":"PDL","n":"329","y":"2023","e":"Susta os efeitos do inciso X do Decreto nº 8.874/2016, inserido pelo Decreto nº 11.498, de 25 de abril de 2023, que inclui a segurança pública e o sistema prisional na lista de setores prioritários elegíveis para a emissão de debêntures incentivadas sob a Lei nº 12.431, de 24 de junho de 2011.","d":"2023-09-21","o":"status_not_published","s":"","tr":"Declaração de Prejudicialidade","u":"2026-09-24","ds":"Declarado prejudicado, nos termos do Art. 164, I, do Regimento Interno da Câmara dos Deputados, o PDL nº 329/2023, de autoria do Deputado Glauber Braga e outros, em virtude da revogação do Decreto nº 11.498/2023, ocorrida em 26 de março de 2024, decorrente da publicação do Decreto nº 11.964/2024.","id":"2389772","law":false,"r":"c"},{"t":"PL","n":"4177","y":"2023","e":"Cria a Fundação de Amparo à Enfermagem Brasileira e dá outras providências.","d":"2023-08-29","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-09-22","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 23/09/2023.","id":"2383368","law":false,"r":"m"},{"t":"PL","n":"4175","y":"2023","e":"Altera o artigo 5º, artigo 9º, § 2º do artigo 12 e artigo 14, todos da Lei nº 5.905, de 12 de julho de 1973 para aumentar a representatividade dos estados no Conselho Federal e nos Conselhos Regionais, e dá outras providencias.","d":"2023-08-29","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2025-02-18","ds":"Desapensação deste do PL nº 4.413, de 2021, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Lei nº 4.413, de 2021, adotado pelo relator da Comissão de Trabalho. (Sessão Deliberativa Extraordinária Presencial de 18/02/2025 - 13:55 - 8ª Sessão)","id":"2383332","law":false,"r":"m"},{"t":"PL","n":"4062","y":"2023","e":"Benefício Especial para Crianças em Tratamento de Hemodiálise.","d":"2023-08-22","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-07-15","ds":"Designada Relatora, Dep. Rogéria Santos (REPUBLIC-BA).","id":"2381565","law":false,"r":"c"},{"t":"PL","n":"3989","y":"2023","e":"Institui o Programa Nacional de Políticas de Prevenção, Proteção e Apoio ao Profissional da Educação Vítima de Violência.","d":"2023-08-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apensação","u":"2025-11-06","ds":"Apensação da proposição PL-4777/2025 à proposição PL-3989/2023.","id":"2380694","law":false,"r":"m"},{"t":"PL","n":"3637","y":"2023","e":"Altera a Lei nº 10.257, de 10 de julho de 2001, para dispor sobre a inclusão de questões de gênero, raça e etnia na execução da política urbana.","d":"2023-07-28","o":"in_progress","s":"Aguardando Parecer","tr":"Devolução ao(à) Relator(a)","u":"2026-03-17","ds":"Devolvida à Relatora, Dep. Talíria Petrone (PSOL-RJ), para se manifestar sobre a emenda apresentada ao substitutivo.","id":"2374515","law":false,"r":"c"},{"t":"PL","n":"3636","y":"2023","e":"Altera a Lei nº 9.504, de 30 de setembro de 1997 (Lei das Eleições), para dispor sobre regras da propaganda eleitoral gratuita de candidaturas de mulheres e de pessoas negras.","d":"2023-07-28","o":"status_not_published","s":"","tr":"Notificações","u":"2025-06-10","ds":"Designada Relatora, Dep. Erika Hilton (PSOL-SP), para o PL 4212/2021, ao qual esta proposição está apensada.","id":"2374514","law":false,"r":"c"},{"t":"PL","n":"3240","y":"2023","e":"Dispõe sobre providências a serem adotadas pelas pessoas submetidas à supervisão do Coaf para o acompanhamento de operações ou propostas de operação que envolvam pessoas expostas politicamente.","d":"2023-06-22","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-11-25","ds":"Encaminhada à publicação. Parecer da Comissão de Finanças e Tributação Publicado em avulso e no DCD de 26/11/2025, Letra A.","id":"2371218","law":false,"r":"c"},{"t":"PL","n":"3089","y":"2023","e":"Dispõe sobre a implementação do “Programa Vini Jr. de Combate ao Racismo” nos estádios e nas arenas esportivas do Brasil.","d":"2023-06-14","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apresentação de Requerimento","u":"2026-02-20","ds":"Apresentação do REQ n. 977/2026 (Requerimento de Urgência (Art. 155 do RICD)), pelas Deputada Sâmia Bomfim (PSOL/SP -Fdr PSOL-REDE) e outros, que \"Requer regime de urgência na apreciação do Projeto de Lei nº 3.089, de 2023.\n\n\n\".","id":"2369380","law":false,"r":"c"},{"t":"PDL","n":"170","y":"2023","e":"Susta a Decisão da Diretoria Colegiada da Agência Nacional de Saúde Suplementar (ANS), de 13 de junho de 2023, que aprovou o índice de reajuste máximo de 9,63% (nove vírgula sessenta e três por cento) para planos de saúde individuais e familiares, com vigência prevista para 1º de maio de 2023 a 30 de abril de 2024.","d":"2023-06-14","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2025-02-25","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 26/02/2025 PÁG 577.","id":"2369407","law":false,"r":"c"},{"t":"PL","n":"2933","y":"2023","e":"Tipifica o crime de ecocídio, inserindo-o na Lei nº 9.605, de 12 de fevereiro de 1998, que “dispõe sobre as sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente, e dá outras providências.”.","d":"2023-06-05","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-11-25","ds":"Parecer do Relator, Dep. Nilto Tatto (PT-SP), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação deste e do Projeto de Lei nº 2.875/2024, apensado, com substitutivo.","id":"2367513","law":false,"r":"c"},{"t":"PL","n":"2766","y":"2023","e":"Altera a Lei 8.112, de 11 de dezembro de 1990 (Estatuto dos Servidores Públicos Federais) para constar como hipótese de penalidades disciplinares atos de assédio moral contra servidores públicos.","d":"2023-05-23","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Aprovação de Requerimento","u":"2023-09-05","ds":"Aprovado requerimento n. 67/2023 da Sra. Professora Luciene Cavalcante que requer envio de Indicação ao Poder Executivo sugerindo ao Ministério da Gestão e Inovação que apresente Projeto de Lei para incluir atos de assédio moral contra servidores públicos como hipótese de penalidade disciplinar por meio da alteração da Lei 8.112, de 11 de dezembro de 1990 (Estatuto dos Servidores Públicos Federais","id":"2364520","law":false,"r":"m"},{"t":"PL","n":"2653","y":"2023","e":"Estabelece prazo de trinta meses para o reajuste das locações comerciais ou residenciais.","d":"2023-05-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2023-11-29","ds":"Designado Relator, Dep. Darci de Matos (PSD-SC), para o PL 6870/2017, ao qual esta proposição está apensada.","id":"2363095","law":false,"r":"c"},{"t":"PL","n":"2601","y":"2023","e":"Altera a Lei nº 9.394, de 20 de dezembro de 1996, que estabelece as Diretrizes e Bases da Educação Nacional.","d":"2023-05-16","o":"status_not_published","s":"","tr":"Expedição de Documento","u":"2026-05-13","ds":"Declarado prejudicado o PL 2601/2023, nos termos do art. 164, inciso I, do Regimento Interno da Câmara dos Deputados.","id":"2362539","law":false,"r":"c"},{"t":"PEC","n":"25","y":"2023","e":"Acrescenta o Capítulo IX ao Título VIII para oferecer diretrizes sobre o direito social ao transporte previsto no art. 6º e sobre o Sistema único de Mobilidade e autoriza a União, Distrito Federal e Municípios a instituírem\ncontribuição pelo uso do sistema viário, destinada ao custeio do transporte público coletivo urbano.","d":"2023-05-16","o":"in_progress","s":"Pronta para Pauta","tr":"Notificações","u":"2026-05-12","ds":"Cancelada a votação nominal em virtude do início da Ordem do Dia do Plenário da Câmara dos Deputados.","id":"2362526","law":false,"r":"c"},{"t":"PL","n":"2473","y":"2023","e":"Altera o art. 67 da Lei nº 9.394, de 20 de dezembro de 1996, para acrescentar o inciso VII para garantia de direitos aos professores readaptados. Altera os arts. 29, §9º, II e III; 29 - C,§3ºe56da Lei nº 8.213, de 24 de julho de 1991 para incluir como direito dos professores readaptados a aposentadoria especial.","d":"2023-05-10","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-06-03","ds":"Designada Relatora, Dep. Leandre (PSD-PR).","id":"2361455","law":false,"r":"m"},{"t":"PL","n":"2387","y":"2023","e":"Altera o art. 2º, §2º da Lei 11.738/2008, para incluir os professores de Educação Infantil como profissionais do magistério.  Altera o art. 61 da Lei nº 9.394, de 20 de dezembro de 1996, para acrescentar o parágrafo segundo para designação de professores de educação infantil pertencentes à carreira do magistério.","d":"2023-05-08","o":"approved","s":"Transformado em Norma Jurídica","tr":"Apresentação de Proposição","u":"2026-02-04","ds":"Apresentação do DOC n. 55/2026 (Ofício do Senado Federal), pelo Senado Federal, que \"Ofício SF nº 4/26, que comunica restituição de Projeto de Lei sancionado\".","id":"2360537","law":true,"r":"m"},{"t":"PL","n":"2156","y":"2023","e":"Dispõe sobre a criação serviço telefônico de recebimento de denúncias - “Disque PARENTE” da Fundação Nacional dos Povos Indígenas-FUNAI, para receber denúncia e dar assistência as especificidades dos Povos Indígenas.","d":"2023-04-26","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-04-10","ds":"Recebimento pelo(a) CFT.","id":"2358498","law":false,"r":"c"},{"t":"PL","n":"2136","y":"2023","e":"Cria o Programa de Acolhimento Social e Psicológico a Comunidades Escolares que tenham sido vítimas de atos de violência.","d":"2023-04-25","o":"in_progress","s":"Tramitando em Conjunto","tr":"Aprovação de Urgência (154, 155 ou 64 CF)","u":"2024-12-09","ds":"Alteração do Regime de Tramitação desta proposição em virtude da alteração do regime do PL 1672/2023, por ter sido aprovado o REQ 1139/2023 que está apensado ao primeiro.","id":"2358256","law":false,"r":"c"},{"t":"PL","n":"2074","y":"2023","e":"Cria o programa de enfrentamento e superação da violência às escolas e altera o art. 20, §1º, da Lei nº 7.716 de 5 de janeiro de 1989.","d":"2023-04-20","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-12-09","ds":"Designada Relatora, Dep. Duda Salabert (PDT-MG), para o PL 5343/2019, ao qual esta proposição está apensada.","id":"2357722","law":false,"r":"m"},{"t":"PL","n":"2062","y":"2023","e":"Acrescenta na Lei nº 9.394, de 20 de dezembro de 1996, o art. 61 - A, para vedar a exigência de registro e pagamento de anuidade em conselho de classe para o efetivo exercício da docência pelos profissionais da educação. Acrescenta o §1º ao art. 1º da Lei nº 9.696, de 1 de setembro de 1998, para tornar dispensável o registro nos Conselhos Regionais de Educação Física para o exercício de docência em educação física.","d":"2023-04-20","o":"in_progress","s":"Pronta para Pauta","tr":"Apresentação de Requerimento","u":"2026-04-14","ds":"Apresentação do REQ n. 19/2026 (Requerimento de Audiência Pública), pela Deputada Professora Luciene Cavalcante (PSOL/SP -Fdr PSOL-REDE), que \"Requer a realização de Audiência Pública para debater o PL 2062/2023, que dispensa o registro nos Conselhos Regionais de Educação Física para o exercício de docência em educação física\n\".","id":"2357670","law":false,"r":"m"},{"t":"PL","n":"2012","y":"2023","e":"Autoriza o Poder Executivo a instituir a Bolsa Auxílio Permanência para estudantes da modalidade Educação de Jovens e Adultos – EJA da rede pública de ensino.","d":"2023-04-19","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-09-09","ds":"Encaminhada à publicação. Parecer da Comissão de Educação Publicado em avulso e no DCD de 10/09/2025, Letra A.","id":"2357412","law":false,"r":"m"},{"t":"PL","n":"1782","y":"2023","e":"Altera dispositivos da Lei nº 11.892, de 29 de dezembro de 2008, que a Rede Federal de Educação Profissional, Científica e Tecnológica.","d":"2023-04-11","o":"status_not_published","s":"","tr":"Notificações","u":"2023-10-26","ds":"Designada Relatora, Dep. Ana Pimentel (PT-MG), para o PL 2699/2011, ao qual esta proposição está apensada.","id":"2355571","law":false,"r":"c"},{"t":"PL","n":"1773","y":"2023","e":"Dispõe sobre a proibição de construção de Usinas Hidrelétricas e Pequenas Centrais Hidrelétricas no Rio Mogi Guaçu.","d":"2023-04-11","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2026-05-13","ds":"Devolvida pelo Relator sem Manifestação.","id":"2355532","law":false,"r":"m"},{"t":"PL","n":"1621","y":"2023","e":"Dispõe sobre o processo de escolha e nomeação dos dirigentes das universidades federais e dá outras providências.","d":"2023-04-05","o":"status_not_published","s":"","tr":"Notificações","u":"2023-10-26","ds":"Designada Relatora, Dep. Ana Pimentel (PT-MG), para o PL 2699/2011, ao qual esta proposição está apensada.","id":"2355013","law":false,"r":"c"},{"t":"PL","n":"1540","y":"2023","e":"Institui a jornada de trabalho de 30 (trinta) horas semanais para profissionais da educação básica que atuam na gestão e na realização de serviços de apoio técnico-administrativo e operacional, inclusive sem redução salarial dos vencimentos e sem prejuízo da evolução funcional, carreira ou demais vantagens, bem como institui o recesso escolar do mês de julho para referidos profissionais.","d":"2023-03-30","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2026-02-03","ds":"Desapensação deste, em face do seu arquivamento, do Projeto de Lei nº 2.531/2021, principal.","id":"2354411","law":false,"r":"m"},{"t":"PL","n":"1344","y":"2023","e":"Institui enfermarias exclusivas para mulheres em situação e/ou processo de abortamento.","d":"2023-03-22","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2024-04-16","ds":"Desapensação deste do PL nº 1.640, de 2022, proposição principal, em face da aprovação da matéria, em Plenário, na forma Substitutivo ao Projeto de Lei nº 1.640, de 2022, adotado pela relatora da Comissão de Constituição e Justiça e de Cidadania (Sessão Deliberativa Extraordinária de 16/04/2024 - 13h55 - 56ª Sessão).","id":"2352554","law":false,"r":"c"},{"t":"PL","n":"1265","y":"2023","e":"Dispõe sobre a prioridade na tramitação dos procedimentos investigatórios que visem à apuração e responsabilização de homicídios, inclusive na modalidade tentada, que tenham como vítimas crianças e adolescentes.","d":"2023-03-21","o":"status_not_published","s":"","tr":"Notificações","u":"2023-12-13","ds":"Devolvido ao Relator, Dep. Rubens Pereira Júnior (PT-MA), para o PL 3388/2008, ao qual esta proposição está apensada.","id":"2352071","law":false,"r":"c"},{"t":"PL","n":"1213","y":"2023","e":"Revoga a Lei nº 13.415, de 16 de fevereiro de 2017, que estabeleceu a chamada “Reforma do Ensino Médio”.","d":"2023-03-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-06-16","ds":"Recebimento pela CE.","id":"2351752","law":false,"r":"c"},{"t":"PDL","n":"78","y":"2023","e":"Susta os efeitos da Portaria nº 521/2021, do Ministério da Educação (MEC), que “Institui o Cronograma Nacional de Implementação do Novo Ensino Médio”.","d":"2023-03-16","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-12-18","ds":"Designado Relator, Dep. Capitão Alden (PL-BA), para o PDL 611/2021, ao qual esta proposição está apensada.","id":"2351699","law":false,"r":"c"},{"t":"PL","n":"1150","y":"2023","e":"Acrescenta dispositivo na Lei nº 6.019/1974 para estabelecer a responsabilidade solidária nos casos de exploração de trabalho em condições análogas à de escravo.","d":"2023-03-14","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-07-22","ds":"Designado Relator, Dep. Bohn Gass (PT-RS), para o PL 861/2023, ao qual esta proposição está apensada.","id":"2351360","law":false,"r":"c"},{"t":"PL","n":"1087","y":"2023","e":"Inclui dispositivo na Lei nº 12.965, de 23 de abril de 2014, para dispor sobre princípios, garantias, direitos e deveres para o uso da internet no Brasil, para determinar que as plataformas digitais implementem sistemas internos de monitoramento da disseminação de discursos de ódio direcionados a mulheres, negros e negras, e LGBTQIA+.","d":"2023-03-13","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-04-25","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 26/04/2023.","id":"2351200","law":false,"r":"c"},{"t":"PL","n":"1050","y":"2023","e":"Dispões sobre a proibição de construção de Usinas Hidrelétricas e Pequenas Centrais Hidrelétricas no Rio Pardo.","d":"2023-03-09","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2023-04-27","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 28/04/2023 PAG 402","id":"2350956","law":false,"r":"m"},{"t":"PL","n":"1041","y":"2023","e":"Dispões sobre a proibição de construção de Usinas Hidrelétricas e Pequenas Centrais Hidrelétricas no Rio Pardo.","d":"2023-03-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento - Relator(a) (Sem Manifestação)","u":"2026-05-13","ds":"Devolvida pelo Relator sem Manifestação.","id":"2350907","law":false,"r":"m"},{"t":"PL","n":"961","y":"2023","e":"Acrescenta os incisos XIII e XIV ao art. 11, da Lei 8.429, de 2 de junho de 1992, para prever como ato de improbidade administrativa o descumprimento de normas que regulamentam o piso salarial profissional.","d":"2023-03-07","o":"in_progress","s":"Aguardando Designação - Aguardando Devolução de Relator(a) que deixou de ser Membro","tr":"Saída de Relator(a) da Comissão - Sem Parecer Apresentado","u":"2026-02-10","ds":"(Instalação da Comissão) O Relator, Dep. Luiz Philippe de Orleans e Bragança, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2350437","law":false,"r":"m"},{"t":"PL","n":"945","y":"2023","e":"Altera a Lei nº 8.112, de 11 de dezembro de 1990 e Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para dispor sobre medidas protetivas à mulher servidora pública em situação de violência\ndoméstica e familiar, prevendo a possibilidade de licença e remoção às vítimas e garantindo o acolhimento e instrução legal por meio da chefia imediata do órgão onde é lotada ou presta serviço, a fim de resguardar\nsua integridade física e psicológica e direitos trabalhistas e para constar como agravante o fato do autor do crime de violência doméstica ser funcionário público.","d":"2023-03-07","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-05-18","ds":"Designada Relatora, Dep. Talíria Petrone (PSOL-RJ), para o PL 3475/2019, ao qual esta proposição está apensada.","id":"2350401","law":false,"r":"m"},{"t":"PL","n":"943","y":"2023","e":"Altera a Lei nº 11.340, de 7 de agosto de 2006 (Lei Maria da Penha), para dispor sobre medidas protetivas à mulher servidora pública em situação de violência doméstica e familiar, garantindo afastamento  remunerado e acomodação em outra unidade para prestação de serviço, a fim de resguardar sua integridade física e psicológica.","d":"2023-03-07","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-05-18","ds":"Designada Relatora, Dep. Talíria Petrone (PSOL-RJ), para o PL 3475/2019, ao qual esta proposição está apensada.","id":"2350392","law":false,"r":"m"},{"t":"PDL","n":"64","y":"2023","e":"Revoga os §§ 1º e 2º do art. 1º do Decreto Legislativo 172 de 21 de dezembro de 2022.","d":"2023-03-07","o":"in_progress","s":"Aguardando Apensação","tr":"Publicação de Proposição","u":"2023-09-06","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 07/09/2023.","id":"2350441","law":false,"r":"c"},{"t":"PL","n":"776","y":"2023","e":"Altera o art. 5º - A, §5º, da Lei nº 6.019, de 3 de janeiro de 1974, para constar a empresa contratante como solidariamente responsável pelas obrigações trabalhistas e previdenciárias referentes ao período em que ocorrer a prestação de serviços.","d":"2023-03-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-04-25","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 26/04/2023 PAG 712","id":"2349758","law":false,"r":"m"},{"t":"PLP","n":"21","y":"2023","e":"Altera a Lei Complementar nº 173, de 27 de maio de 2020, para contagem do tempo de período aquisitivo de anuênios, triênios, quinquênios, sexta-parte, licença-prêmio e demais mecanismos equivalentes, durante\nperíodo de enfrentamento ao Coronavírus SARS-CoV-2 (Covid-19), e dá outras providências.","d":"2023-02-09","o":"approved_with_another_bill","s":"Arquivada","tr":"Prejudicialidade (Plenário)","u":"2025-08-26","ds":"Matéria aprovada na forma do Substitutivo ao Projeto de Lei Complementar nº 143, de 2020, da Comissão de Finanças e Tributação (Sessão Deliberativa Extraordinária Presencial de 26/08/2025 - 13:55 - 163ª Sessão). Esta proposição fica prejudicada, na forma do art. 191 do RICD.","id":"2348300","law":false,"r":"m"},{"t":"PLP","n":"19","y":"2023","e":"Altera a Lei Complementar nº 179, de 24 de fevereiro de 2021, que “Define os objetivos do Banco Central do Brasil e dispõe sobre sua autonomia e sobre a nomeação e a exoneração de seu Presidente e de seus Diretores” para caracterizar o Banco Central do Brasil como autarquia de natureza especial caracterizada pela subordinação hierárquica ao Presidente da República e estabelecer critérios econômicos e sociais para as nomeações, composição e condução das atividades de competência da autoridade monetária.","d":"2023-02-07","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-03-29","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 30/03/2023 PAG 364","id":"2347238","law":false,"r":"c"}];
